"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant0 from "./components/animated-text/variants/02-blur-highlight";
import Variant1 from "./components/animated-text/variants/03-progressive-blur-highlight";
const variants = { "blur-highlight": Variant0, "progressive-blur-highlight": Variant1 };
export interface ArtemisTextHighlightProps {
  className?: string;
  variant?: "blur-highlight" | "progressive-blur-highlight";
}
export function ArtemisTextHighlight({
  className,
  variant = "blur-highlight",
}: ArtemisTextHighlightProps) {
  const View = variants[variant];
  return (
    <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}>
      <View />
    </ArtemisScope>
  );
}
